+describe('ChatOrchestrator tool-loop recovery', () => {
+  it('feeds a schema rejection to the provider before the corrected tool call', async () => {
+    const registry = new ToolRegistry();
+    let executorCalls = 0;
+    let rejectionSeenByProvider = '';
+    let round = 0;
+    registry.register(
+      {
+        name: 'get_weather',
+        description: 'Get weather',
+        inputSchema: {
+          type: 'object',
+          properties: {location: {type: 'string'}},
+          required: ['location'],
+        },
+      },
+      async () => {
+        executorCalls += 1;
+        return 'sunny';
+      }
+    );
+
+    const provider: AIProvider = {
+      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
+        round += 1;
+        if (round === 2) {
+          const lastMessage = params.messages[params.messages.length - 1];
+          const content = Array.isArray(lastMessage.content) ? lastMessage.content[0] : undefined;
+          rejectionSeenByProvider = content?.type === 'tool_result' ? content.content : '';
+          yield {type: 'text', text: 'Recovered'};
+          yield {type: 'stop', stopReason: 'end_turn'};
+          return;
+        }
+        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
+        yield {type: 'stop', stopReason: 'tool_use'};
+      },
+      async generateStructured<T>(): Promise<T> {
+        return {} as T;
+      },
+    };
+
+    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
+    const reply = await orchestrator.processMessage(createSession('Weather?'));
+
+    expect({reply, executorCalls, rejectionSeenByProvider}).toEqual({
+      reply: 'Recovered',
+      executorCalls: 0,
+      rejectionSeenByProvider: expect.stringMatching(/location.*required/i),
+    });
+  });
+});
+
